# Dated local cash movements; classifications never infer household income.
build_transaction_features<-function(transactions,daily_balances,category_mapping,coverage,customer_id,own_account_ids,as_of,information_cutoff,lookback_days,currency,context=NULL){times<-.cr_rb_window(as_of,information_cutoff,lookback_days,context);anchor<-times$anchor;cutoff<-times$cutoff;ctx<-times$context;days<-times$days;start<-times$start;.cr_rf_text(customer_id,'customer_id');accounts<-.cr_rf_strings(own_account_ids,'own_account_ids',FALSE);.cr_rf_text(currency,'currency');complete<-.cr_rb_coverage(coverage,cutoff,start,anchor);if(!is.null(ctx$currency)&&ctx$currency!=currency) .cr_error('TARGET_MISMATCH','Context currency differs from cashflow reporting currency');if(!.cr_object(category_mapping)) .cr_error('RETAIL_MAPPING','Dated local category mapping required');.cr_data_required(category_mapping,c('mapping_id','version','known_at','categories'));if(.cr_data_date(category_mapping$known_at,'mapping.known_at')>cutoff) .cr_error('RETAIL_DATE','Category mapping unavailable at cutoff');categories<-category_mapping$categories;allowed<-sort(c('SALARY','OTHER_INCOME','BUSINESS_REVENUE','CONSUMPTION','DEBT_SERVICE','BORROWING','REFUND','OWN_TRANSFER','OWNER_DRAW','TAX','UNKNOWN'));if(!is.list(categories)||(length(categories)&&(is.null(names(categories))||any(!nzchar(names(categories)))))||any(!vapply(categories,function(v)is.character(v)&&length(v)==1&&!is.na(v)&&v%in%allowed,logical(1)))) .cr_error('RETAIL_MAPPING','Unsupported local category mapping');release<-.cr_rf_releases(transactions,'transaction_id',cutoff,'transactions');visible<-list()
 for(row in release$rows){.cr_data_required(row,c('account_id','posted_at','value_at','amount','currency','kind','category_code'));posted<-.cr_data_date(row$posted_at,'posted_at');.cr_data_date(row$value_at,'value_at');.cr_rf_text(row$category_code,'category_code');if(posted>.cr_data_date(row$known_at,'known_at')) .cr_error('RETAIL_DATE','Transaction receipt cannot precede posting');if(!(row$account_id%in%accounts)||row$currency!=currency) .cr_error('RETAIL_ENTITY','Transactions must match supplied own accounts and currency');.cr_rf_number(row$amount,'amount');if(!(row$kind%in%c('ORIGINAL','REVERSAL'))) .cr_error('RETAIL_TRANSACTION','Declare ORIGINAL or REVERSAL kind');if(posted<=anchor)visible[[row$transaction_id]]<-row}
 reversal_totals<-list();classified<-list();pairs<-list();for(key in sort(names(visible))){row<-visible[[key]];original<-row;if(row$kind=='REVERSAL'){original<-if(is.null(row$reverses_transaction_id))NULL else visible[[row$reverses_transaction_id]];if(is.null(original)||original$kind!='ORIGINAL'||original$account_id!=row$account_id||original$posted_at>row$posted_at||row$amount==0||original$amount==0||((row$amount>0)==(original$amount>0))) .cr_error('RETAIL_REVERSAL','Reversal needs an earlier visible same-account original of opposite sign');reversal_totals[[original$transaction_id]]<-c(reversal_totals[[original$transaction_id]],abs(row$amount))};category<-categories[[original$category_code]];if(is.null(category))category<-'UNKNOWN';if(category=='OWN_TRANSFER'){.cr_data_required(original,c('transfer_id','counterparty_own_account_id'));.cr_rf_text(original$transfer_id,'transfer_id');if(!(original$counterparty_own_account_id%in%accounts)||original$counterparty_own_account_id==original$account_id) .cr_error('RETAIL_TRANSFER','Own transfer requires a distinct explicitly owned counterparty account');if(row$kind=='ORIGINAL')pairs[[original$transfer_id]]<-c(pairs[[original$transfer_id]],list(row))};if(start<.cr_data_date(row$posted_at,'posted_at')&&.cr_data_date(row$posted_at,'posted_at')<=anchor)classified[[length(classified)+1L]]<-list(transaction_id=key,account_id=row$account_id,posted_at=row$posted_at,value_at=row$value_at,amount=row$amount,category=category,kind=row$kind,reverses_transaction_id=row$reverses_transaction_id,release_seq=row$release_seq)}
 for(key in names(reversal_totals))if(.cr_loss_sum(reversal_totals[[key]])>abs(visible[[key]]$amount)) .cr_error('RETAIL_REVERSAL','Total reversals exceed original amount');unmatched<-character();for(transfer_id in sort(names(pairs))){legs<-pairs[[transfer_id]];if(length(legs)==1)unmatched<-c(unmatched,transfer_id)else if(length(legs)!=2||legs[[1]]$account_id!=legs[[2]]$counterparty_own_account_id||legs[[2]]$account_id!=legs[[1]]$counterparty_own_account_id||.cr_loss_sum(vapply(legs,`[[`,numeric(1),'amount'))!=0) .cr_error('RETAIL_TRANSFER','Own-transfer legs must match two opposite same-currency account movements')};classified<-.cr_rf_sort(classified,c('posted_at','transaction_id'));bycategory<-setNames(rep(list(numeric()),length(allowed)),allowed);for(row in classified)bycategory[[row$category]]<-c(bycategory[[row$category]],row$amount);totals<-lapply(bycategory,function(v)list(credits=.cr_loss_sum(v[v>0]),debits=.cr_loss_sum(-v[v<0]),net=.cr_loss_sum(v),transaction_count=length(v)));amounts<-vapply(classified,`[[`,numeric(1),'amount');inflows<-.cr_loss_sum(amounts[amounts>0]);outflows<-.cr_loss_sum(-amounts[amounts<0]);external<-Filter(function(r)!(r$category%in%c('OWN_TRANSFER','OWNER_DRAW')),classified);bydate<-list();for(row in external)bydate[[row$posted_at]]<-c(bydate[[row$posted_at]],row$amount);daily_net<-vapply(seq_len(days),function(i).cr_loss_sum(bydate[[as.character(start+i)]]),numeric(1));mean<-.cr_loss_sum(daily_net/days);scale<-max(abs(daily_net));sd<-if(scale==0)0 else scale*sqrt(.cr_loss_sum((daily_net/scale-mean/scale)^2/days));if(!is.finite(sd)) .cr_error('NUMERICAL_FAILURE','Daily cashflow volatility outside finite range')
 balances_release<-.cr_rf_releases(daily_balances,'balance_id',cutoff,'daily balances');grid<-list();balance_lineage<-list();for(row in balances_release$rows){.cr_data_required(row,c('account_id','observed_at','closing_balance','currency'));observed<-.cr_data_date(row$observed_at,'observed_at');if(observed>.cr_data_date(row$known_at,'known_at')) .cr_error('RETAIL_DATE','Balance receipt precedes observation');if(!(row$account_id%in%accounts)||row$currency!=currency) .cr_error('RETAIL_ENTITY','Daily balances must match own accounts and currency');.cr_rf_number(row$closing_balance,'closing_balance');if(!(start<observed&&observed<=anchor))next;key<-.cr_data_key(row,c('account_id','observed_at'));if(!is.null(grid[[key]])) .cr_error('DATA_DUPLICATE','One resolved daily balance per own account required');grid[[key]]<-row$closing_balance;balance_lineage[[length(balance_lineage)+1L]]<-list(balance_id=row$balance_id,release_seq=row$release_seq)}
 buffer<-numeric();overdraft_account_days<-0;complete_balance_days<-0;for(offset in seq_len(days)){date<-as.character(start+offset);values<-unlist(lapply(accounts,function(account)grid[[.cr_data_key(list(account_id=account,observed_at=date),c('account_id','observed_at'))]]),use.names=FALSE);overdraft_account_days<-overdraft_account_days+sum(values<0);if(length(values)==length(accounts)){buffer<-c(buffer,.cr_loss_sum(values));complete_balance_days<-complete_balance_days+1}};known_income<-.cr_loss_sum(vapply(totals[c('SALARY','OTHER_INCOME')],`[[`,numeric(1),'net'));known_expense<- -.cr_loss_sum(vapply(totals[c('CONSUMPTION','DEBT_SERVICE','TAX')],`[[`,numeric(1),'net'));unknown_volume<-.cr_loss_sum(abs(bycategory$UNKNOWN));gross_volume<-.cr_loss_sum(abs(amounts))
 .cr_result(list(customer_id=customer_id,own_account_ids=as.list(sort(accounts)),as_of=as_of,information_cutoff=information_cutoff,currency=currency,lookback_days=days,coverage_complete=complete,category_totals=totals,known_gross_inflows=inflows,known_gross_outflows=outflows,known_net_cashflow=.cr_loss_sum(c(inflows,-outflows)),known_external_net_cashflow=.cr_loss_sum(vapply(external,`[[`,numeric(1),'amount')),known_classified_income=known_income,classified_income=if(complete)known_income else NULL,known_classified_expense=known_expense,classified_expense=if(complete)known_expense else NULL,daily_external_net_cashflow=as.list(daily_net),known_daily_net_population_sd=sd,daily_net_population_sd=if(complete)sd else NULL,unknown_category_absolute_volume=unknown_volume,unknown_category_fraction=if(gross_volume==0)NULL else unknown_volume/gross_volume,complete_balance_days=complete_balance_days,missing_balance_account_days=days*length(accounts)-length(grid),known_overdraft_account_days=overdraft_account_days,overdraft_account_days=if(complete&&length(grid)==days*length(accounts))overdraft_account_days else NULL,minimum_observed_complete_household_balance=if(length(buffer))min(buffer)else NULL,mean_observed_complete_household_balance=if(length(buffer)).cr_loss_sum(buffer/length(buffer))else NULL,classified_transactions=classified,unmatched_own_transfer_ids=as.list(unmatched)),'retail_features.build_transaction_features',currency,ctx,diagnostics=list(mapping_id=category_mapping$mapping_id,mapping_version=category_mapping$version,mapping_fingerprint=.cr_hash(category_mapping),coverage=coverage,excluded_transaction_releases=release$excluded,excluded_balance_releases=balances_release$excluded,balance_lineage=.cr_rf_sort(balance_lineage,'balance_id')),limitations=list('Cashflows use posting dates; value dates are retained without silently changing the window. Reversals retain their own cash date and inherit original classification; both legs neutralize within a common window, while cross-window reversals remain actual cash movements. Refunds, borrowing, business sales and owner/own-account transfers are not household income. Missing categories remain UNKNOWN rather than consumer spending. Complete history is asserted by supplied coverage; cash volatility from incomplete records is only a known-record statistic. Own-account ownership and local categories are asserted, not inferred.'))}
